    listSources: {
        parameters: {
            query?: {
                /** @description Engine to rank for. Default: `MULTITAP_SELECTION_DEFAULT_ENGINE`, else the only engine there is. */
                engine?: string;
                /** @description Sources above the engine's live limit: `off` marks them unplayable, `prepareOnly`/`on` playable once prepared. Default: configured. */
                highRes?: "off" | "prepareOnly" | "on";
                /** @description Default `addon`. */
                sort?: "addon" | "rank";
                /** @description Answer at once and send results as `streams.partial` events. Default `false`. */
                incremental?: "true" | "false";
                /** @description Attach `explain` to each candidate: the ordered rules that moved its score (summing exactly to `score`), the weights used and the playability reason. Also applies to `streams.partial` events. Default `false`; without it the response is unchanged. */
                explain?: "true" | "false";
                /** @description Preferred audio languages for ranking, comma-separated, most preferred first: ISO 639-2 (B or T) or 639-3 codes. Default: the profile's audio languages (with `profileId`), else the instance's `MULTITAP_SELECTION_PREFERRED_LANGUAGE`. */
                preferredLanguage?: string;
                /** @description Rank candidates with this `bingeGroup` up (`binge.matchBonus`), e.g. the previous episode's session `bingeGroup`. */
                preferBingeGroup?: string;
                /** @description List for a profile: its audio languages are the preferred languages when `preferredLanguage` is absent (before the instance default), and the source it last played for this video is flagged `lastUsed` and ranked up (`lastSource.matchBonus`). An unknown profile is a `400`. */
                profileId?: string;
            };
            header?: never;
            path: {
                /** @description Content type: `movie`, `series`, `channel`, `tv`, … */
                type: string;
                /** @description Video id: the item id for a movie, `{id}:{season}:{episode}` for an episode. */
                videoId: string;
            };
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description The candidates and every addon asked */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["SourceList"];
                };
            };
            /** @description Started: results follow as `streams.partial` events */
            202: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["SourceListStarted"];
                };
            };
            /** @description The request failed validation, or the engine is unknown */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description The key is valid but lacks the scope this route needs */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
            /** @description Not found, or the API key is missing, invalid or revoked */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/problem+json": components["schemas"]["Problem"];
                };
            };
        };
    };
